const PREFS=[['position','Posizione',5],['price','Prezzo rispetto al mio budget',5],['space','Spazi e distribuzione',4],['light','Luce naturale e atmosfera',4],['feel','Sensazione personale',4],['condition','Stato e lavori necessari',3],['commute','Vicinanza ai luoghi importanti',3]];
