function old_intentExpert(e,cat,serviceId){const s=SERVICE.find(x=>x.id===serviceId),h=H();if(!s)return;track('expert_offer_view',{expertId:e.id,propertyId:h.id,service:serviceId,price:s.price});confirmIntent(`${s.name} · ${e.name}`,s.price,`Richiesta simulata relativa a: ${CATEGORIES.find(x=>x[0]===cat)?.[1]||'gap tecnico'}. Nessuna chat, videocall o ispezione sarà effettivamente erogata.`,()=>{S.intents.push({id:uid(),time:now(),type:'expert',propertyId:h.id,expertId:e.id,service:serviceId,category:cat,price:s.price});track('payment_intent',{product:'expert_'+serviceId,propertyId:h.id,price:s.price,realPayment:false});persist();setTimeout(()=>demoExpertReportOffer(e,cat,serviceId),150)})}
function old_demoExpertReportOffer(e,cat,serviceId){const h=H();openModal(`<h2>Richiesta registrata</h2><div class="notice">Hai espresso un'intenzione di pagamento. Non è stato effettuato alcun addebito né erogato un servizio professionale.</div><p>Per continuare il test puoi integrare un <b>report professionale dimostrativo</b> nel dossier e vedere come cambierebbe l'analisi.</p><button class="btn btn-primary btn-full mt2" id="integrateExpert">Verifica report dell'esperto (simulazione)</button><button class="btn btn-outline btn-full mt2" data-close>Non adesso</button>`);$('#integrateExpert').onclick=async()=>{const report={id:uid(),expertId:e.id,expertName:e.name,category:cat,categoryLabel:CATEGORIES.find(x=>x[0]===cat)?.[1]||cat,service:serviceId,date:now(),simulation:true,summary:`Documento illustrativo per ${cat}: le informazioni presenti non consentono di certificare la conformità dell’immobile. È necessario acquisire le evidenze originali e, dove previsto, eseguire un sopralluogo o una verifica da professionista abilitato.`,findings:[{item:'Evidenza documentale',status:'da approfondire',source:'Scenario dimostrativo',action:'Richiedere il documento originale e verificarlo'}]};h.expertReports.push(report);h.reportScenario=true;persist();track('expert_report_demo_integrated',{propertyId:h.id,category:cat});closeModal();toast('Report dimostrativo integrato: aggiorno l’analisi.');await analyze(h);tab='experts';render()}}
function old_exportDossier(h){if(!h.unlocked)return toast('Dossier non sbloccato');const t=[`MIND THE GAP — DOSSIER SPERIMENTALE`,h.name,h.link,`Rispondenza alle esigenze: ${fit(h)}/100`,`Completezza del dossier: ${readiness(h)??'—'}/100`,h.analysis?.mode==='demo'?'ANALISI DEMO (NON AI)':'ANALISI PRELIMINARE AI','',...gapList(h).flatMap(g=>[g.title,g.reason,'Azione: '+g.action,'Fonte: '+(g.source||'non specificata'),'']),...h.expertReports.map(r=>'REPORT DIMOSTRATIVO: '+r.summary),'',`Le informazioni non costituiscono perizia tecnica.`].join('\n');const u=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='MTG_Dossier_'+h.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);track('dossier_export',{propertyId:h.id})}
function downloadJSON(name,o){const u=URL.createObjectURL(new Blob([JSON.stringify(o,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
async function initSupabase(){if(!aiReady())return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');supabase=createClient(CFG.supabaseUrl,CFG.supabasePublishableKey);const {data}=await supabase.auth.getSession();session=data.session;supabase.auth.onAuthStateChange((_,newSession)=>{session=newSession;$('#navAccount').textContent=authenticated()?'Il mio account':'Accedi'});render()}catch(e){console.error(e);toast('Supabase non disponibile: puoi usare la demo locale.')}}

function bind(){old_bind();if(view==='compare'){$$('[data-buy-compare]').forEach(b=>b.onclick=()=>{const h=S.homes.find(x=>x.id===b.dataset.buyCompare);if(!h)return;if(!allowedDossier(h)){go('property',h.id);tab='questions';render();toast('Rispondi ad almeno una domanda di questa casa.');return}intentDossier(h)})}if(view==='onboarding'||(!buyerReady()&&view!=='method')){$('#addPersonalCriterion')?.addEventListener('click',()=>{const el=$('#newCriterion'),n=el?.value.trim();if(!n)return;appendCriteria(n);const newest=PREFS.find(c=>c[1].toLowerCase()===n.toLowerCase());if(!newest)return;const w=profileWeights();if(!(newest[0] in w)){S.buyerProfile ||= {};S.buyerProfile.weights ||= {};S.buyerProfile.weights[newest[0]]=3;}const rows=$('#newCriterionRows');if(rows&&!$('#bw-'+newest[0]))rows.insertAdjacentHTML('beforeend',`<div class="buyer-weight"><label for="bw-${newest[0]}">${safe(newest[1])}</label><input id="bw-${newest[0]}" type="range" min="0" max="5" step="1" value="3" data-buyer-weight="${newest[0]}"><strong id="bv-${newest[0]}">3/5</strong></div>`);const slider=$('#bw-'+newest[0]);if(slider)slider.oninput=()=>{$('#bv-'+newest[0]).textContent=slider.value+'/5'};el.value='';});}}
/* === MTG 2026: buyer-led journey, evidence separate from user closure === */
function currentCriteria(){return [...PREFS]}
function ensureHomeFlow(h){h.questionStates ||= {};h.questionsVisited ||= false;h.shownQuestionKeys ||= [];h.decisionReason ||= '';h.specialRequest ||= '';h.visitStatus ||= 'not_visited';h.visitNotes ||= '';h.visitDate ||= '';h.phaseHistory ||= [];}
function qKey(g){return g.check_id ? 'check:'+g.check_id : `${g.category||'other'}:${(g.title||'').toLowerCase().replace(/[^a-z0-9àèéìòù]+/g,'-').slice(0,85)}`}
// Questions represent useful buyer actions, not each internal verification.
function topicOf(q){
 const t=String((q.title||'')+' '+(q.check_id||'')).toLowerCase();
 const c=q.category||'other';
 const rules={
  legal:[['titolarita',/propriet[aà]|titolari|ipotec|gravam|pignor|pregiudiz|visur[ae] ipotec/],['occupazione',/liber[oa] al rogito|consegn|occupat|locat|inquilin/],['contratto',/preliminar|proposta|caparra|contratt/]],
  price:[['costi',/cost[io]|spes[ae]|oner[ei]|impost|notaio|commission|accessor/],['prezzo',/prezzo|valore|richiest/]],
  urban:[['planimetria',/planimetr|distribuzion|difformit[aà]/],['lavori',/titoli ediliz|modific|paret|ristruttur|urbanistic|conformit[aà]/],['visura',/visur|catast/]],
  condo:[['spese',/spes[ae]|cost[io]/],['lavori',/straordinar|deliber|assemble|verbali/],['regolamento',/regolament/]],
  energy:[['ape',/ape|classe energet|attestato/],['impianto',/riscaldament|consum/]],
  space:[['misure',/superfic|metri quadr|misur/],['layout',/planimetr|locali|distribuzion/]],
  condition:[['umidita',/umid|infiltr|muff/],['impianti',/impiant|elettric|idraulic/]],
  location:[['collegamenti',/trasport|collegament|serviz/],['zona',/quartier|rumor|posizion/]],
  risk:[['rischi',/alluvion|fran|amiant|rischio|vincol/]]
 };
 const hit=(rules[c]||[]).find(([,re])=>re.test(t));
 return c+':'+(hit?hit[0]:String(q.check_id||q.title||'').toLowerCase().replace(/[^a-z0-9]+/g,'_').slice(0,35));
}
function questionList(h){
 ensureHomeFlow(h);
 const raw=gapList(h).map((g,i)=>({...g,key:qKey(g),index:i,state:h.questionStates[qKey(g)]||{answer:'',closed:false},phase:g.phase||'any'}));
 const severityScore=x=>({critical:0,high:1,medium:2,low:3})[x.severity]??3;
 raw.sort((a,b)=>severityScore(a)-severityScore(b)||a.index-b.index);
 const seen=new Set(); const unique=[];
 for(const q of raw){const topic=topicOf(q);if(seen.has(topic))continue;seen.add(topic);unique.push(q)}
 return unique;
}

function visibleQuestions(h){return questionList(h).filter(x=>x.phase!=='after_visit'||h.visitStatus==='visited'||!!x.state.answer)}
function reconcileQuestionStates(h,newAnalysis){
 ensureHomeFlow(h);
 const previous=questionList(h);
 for(const g of (newAnalysis?.gaps||[])){
  const k=qKey(g);if(h.questionStates[k])continue;
  const candidates=previous.filter(p=>p.category===g.category&&p.state.answer);
  if(candidates.length===1){h.questionStates[k]={...candidates[0].state,migratedFrom:candidates[0].key};}
  else if(candidates.length>1){const tokens=(t)=>new Set(String(t).toLowerCase().split(/[^a-zàèéìòù0-9]+/).filter(x=>x.length>3));const dest=tokens(g.title);const best=candidates.map(p=>({p,score:[...tokens(p.title)].filter(x=>dest.has(x)).length})).sort((a,b)=>b.score-a.score)[0];if(best&&best.score>=2)h.questionStates[k]={...best.p.state,migratedFrom:best.p.key};}
 }
}
// A question bank is NOT a mandatory questionnaire. The buyer sees a small adaptive batch.
const FIRST_BATCH_SIZE=3, NEXT_BATCH_SIZE=2;
function questionPriority(q,h){
 const severity={critical:100,high:75,medium:45,low:15}[q.severity]||15;
 const answer=q.state?.answer?.trim()? -35:0;
 const followUpBonus=q.parent_question?45:0;
 const stage=q.phase==='after_visit'&&h.visitStatus!=='visited'?-500:0;
 const relevance=(q.category==='urban'?4:0);
 const buyerWeights=profileWeights();
 const preferenceMap={price:['price'],space:['space'],location:['position','commute'],condition:['condition'],energy:['condition'],condo:['price','condition'],risk:['condition'],urban:['space'],legal:['price']};
 const buyerPriority=Math.max(0,...(preferenceMap[q.category]||[]).map(x=>Number(buyerWeights[x]||0)))*2;
 return severity+answer+stage+relevance+buyerPriority+followUpBonus;
}
function questionPool(h){return visibleQuestions(h).sort((a,b)=>questionPriority(b,h)-questionPriority(a,h)||a.index-b.index)}
function ensureAdaptiveBatch(h){
 ensureHomeFlow(h);
 if(!Array.isArray(h.shownQuestionKeys))h.shownQuestionKeys=[];
 const pool=questionPool(h);
 const validKeys=new Set(pool.map(q=>q.key));
 h.shownQuestionKeys=[...new Set(h.shownQuestionKeys)].filter(k=>validKeys.has(k));
 if(!h.shownQuestionKeys.length){
  const selected=[];const categories=new Set();
  for(const q of pool){if(!categories.has(q.category)){selected.push(q);categories.add(q.category)}if(selected.length>=FIRST_BATCH_SIZE)break}
  for(const q of pool){if(selected.length>=FIRST_BATCH_SIZE)break;if(!selected.includes(q))selected.push(q)}
  h.shownQuestionKeys=selected.map(q=>q.key);
 }
 // Retain historic questions/answers. When the user records a visit show the top new visit questions.
 const selected=new Set(h.shownQuestionKeys);
 if(h.visitStatus==='visited'&&!h.visitQuestionsActivated){
  const post=pool.filter(q=>q.phase==='after_visit'&&!selected.has(q.key)).slice(0,2);
  h.shownQuestionKeys.push(...post.map(q=>q.key));h.visitQuestionsActivated=true;
 }
 // Adaptive follow-up questions are added to the visible stream when created.
 return h.shownQuestionKeys;
}
function currentBatch(h){const keys=new Set(ensureAdaptiveBatch(h));const all=questionPool(h).filter(q=>keys.has(q.key));const unanswered=all.filter(q=>!q.state.answer?.trim());const answered=all.filter(q=>q.state.answer?.trim());return [...unanswered.slice(0,answered.length?2:3),...answered.slice(-1)].slice(0,3)}
function remainingQuestions(h){const keys=new Set(ensureAdaptiveBatch(h));return questionPool(h).filter(q=>!keys.has(q.key))}
function expandBatch(h){const extra=remainingQuestions(h).slice(0,NEXT_BATCH_SIZE);h.shownQuestionKeys.push(...extra.map(q=>q.key));persist();track('adaptive_questions_more',{propertyId:h.id,count:extra.length});render()}
function hasBuyerInput(h){return questionList(h).some(q=>!!q.state.answer?.trim())}
function markFollowUps(h,sourceKey,gaps){
 if(!Array.isArray(gaps)||!h.analysis)return 0;
 const existing=new Set(questionList(h).map(x=>x.key));const existingTopics=new Set(questionList(h).map(topicOf));let added=0;
 for(const g of gaps.slice(0,2)){
  if(!g||!CATEGORIES.some(([id])=>id===g.category)||typeof g.title!=='string'||g.title.length<14||!g.title.includes('?'))continue;
  const check_id=String(g.check_id||'').replace(/[^a-z0-9_]/gi,'').slice(0,72);
  if(!check_id)continue;
  const item={category:g.category,check_id,phase:g.phase==='after_visit'?'after_visit':'any',title:g.title.slice(0,230),severity:['critical','high','medium','low'].includes(g.severity)?g.severity:'medium',reason:String(g.reason||'Approfondimento richiesto dalla risposta.').slice(0,500),action:String(g.action||'Richiedi il documento pertinente.').slice(0,500),source:String(g.source||'Risposta buyer').slice(0,160),status:'open',parent_question:sourceKey};
  const key=qKey(item),topic=topicOf(item);if(existing.has(key)||existingTopics.has(topic))continue;
  h.analysis.gaps.push(item);existing.add(key);existingTopics.add(topic);h.shownQuestionKeys ||= [];
  if(item.phase==='any'||h.visitStatus==='visited')h.shownQuestionKeys.push(key);
  added++;
 }
 return added;
}
function questionCounts(h){const q=visibleQuestions(h),all=questionList(h);return {total:q.length,answered:q.filter(x=>x.state.answer?.trim()).length,closed:q.filter(x=>x.state.closed).length,open:q.filter(x=>!x.state.closed).length,postVisitPending:all.filter(x=>x.phase==='after_visit'&&h.visitStatus!=='visited'&&!x.state.answer).length};}
function questionDone(h){return !!h.analysis && hasBuyerInput(h)}
function allowedDossier(h){return !!h.analysis && (hasBuyerInput(h)||h.unlocked)}
function appendCriteria(name,weight=3){const n=name.trim().slice(0,80);if(!n)return;const existing=PREFS.find(x=>x[1].toLowerCase()===n.toLowerCase());if(existing)return;const id='personal_'+n.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').slice(0,48);if(PREFS.some(x=>x[0]===id))return;PREFS.push([id,n,weight]);for(const h of S.homes){h.ratings ||= {};h.ratings[id] ??= null;}}
for(const c of (S.buyerProfile?.customCriteria||[])){appendCriteria(c.name,c.weight)}
for(const h of S.homes)ensureHomeFlow(h);
function onboardingPage(){const text=old_onboardingPage().replace('Il tuo profilo buyer','Le tue esigenze').replace('Partiamo da ciò che conta <span class="accent">per te.</span>','Che cosa cerchi nella tua <span class="accent">prossima casa?</span>').replace('Salva le priorità e aggiungi un immobile','Salva e continua');return text.replace('<button class="btn btn-primary btn-full mt3" type="submit">',`<div class="field mt3"><label class="label" for="newCriterion">Vuoi aggiungere un criterio personale?</label><div class="flex wrap"><input id="newCriterion" class="input" placeholder="Es. terrazzo, vicinanza ai genitori" maxlength="80" style="flex:1"><button class="btn btn-outline" type="button" id="addPersonalCriterion">Aggiungi criterio</button></div><div id="newCriterionRows"></div></div><button class="btn btn-primary btn-full mt3" type="submit">`)}
function saveBuyer(e){const oldCustom=S.buyerProfile?.customCriteria||[];const extras=PREFS.filter(c=>c[0].startsWith('personal_')).map(c=>({id:c[0],name:c[1],weight:Number($(`#bw-${c[0]}`)?.value??3)}));old_saveBuyer(e);if(!S.buyerProfile?.completed)return;S.buyerProfile.customCriteria=extras;for(const c of extras)S.buyerProfile.weights[c.id]=c.weight;persist();}
function headerH(h){let html=old_headerH(h);html=html.replace("['overview','Riepilogo'],['gaps','Verifiche e documenti']", "['overview','Riepilogo'],['questions','Domande da chiarire'],['gaps','Verifiche e dossier']"); // old header uses sections for menu; local replacement works
 html=html.replace("['experts','Professionisti']", "['experts','Professionisti'],['decision','La mia decisione']");
 html=html.replace('<button class="btn btn-outline btn-small" id="editHome">', '<button class="btn btn-outline btn-small" id="addAnotherHome">+ Valuta un’altra casa</button><button class="btn btn-outline btn-small" id="editHome">');
 return html;}
function propertyPage(){const h=H();if(!h)return '<div class="container section">Immobile non trovato</div>';ensureHomeFlow(h);
 const pages={overview:overviewTab,questions:questionsTab,gaps:gapsTab,preferences:prefsTab,documents:documentsTab,chat:chatTab,experts:expertsTab,decision:decisionTab,compare:compareInner};
 return headerH(h)+`<div class="workspace-content">${(pages[tab]||overviewTab)(h)}</div></section></div>`;
}
function journeyHeader(h){const qs=questionCounts(h);const steps=[['Esigenze',buyerReady()],['Annuncio',!!h.analysis],['Prime risposte',hasBuyerInput(h)],['Dossier',!!h.unlocked],['Decisione',!!h.decisionReview]];return `<div class="journey-steps">${steps.map(([title,done],i)=>`<div class="journey-step ${done?'journey-done':''}"><b>${done?'✓':i+1}</b><span>${title}</span></div>`).join('')}</div><div class="journey-summary">${qs.answered} risposte raccolte · <strong>${qs.open} questioni aperte</strong> · ${qs.closed} chiuse da te <span class="tiny">(la chiusura non significa verifica documentale)</span></div>`}
function previewPanel(h){const qs=questionCounts(h);const f=fit(h),r=readiness(h);return `<section class="surface-card"><div class="section-line"><div><h3>La prima valutazione della casa</h3><p class="small muted">Quello che emerge dalle informazioni disponibili e dalle tue risposte.</p></div><span class="state-pill">${qs.answered}/${qs.total} risposte</span></div><div class="summary-scores">${scoreCard('Quanto fa per te',f,`Valutato il ${fitCoverage(h)}% delle tue priorità.`)}${scoreCard('Copertura delle informazioni',r,'Indice basato su annuncio, documenti ed eventuali verifiche. Non certifica conformità.')}</div><div class="coverage-row"><div><strong>${qs.open}</strong><span>aperte</span></div><div><strong>${qs.closed}</strong><span>chiuse da te</span></div><div><strong>${h.docs.length}</strong><span>documenti</span></div></div></section>`}
function dossierOffer(h){const q=questionCounts(h);if(h.unlocked)return `<div class="notice">Dossier completo disponibile per questo immobile. Nessun addebito è stato effettuato nel test.</div><button class="btn btn-outline" id="exportDossier">Esporta il dossier</button>`;return `<div class="dossier-offer"><strong>49 €</strong><span>Per questo immobile · acquisto simulato</span><p>Elenco completo delle verifiche, risposte, fonti, documenti e aggiornamenti.</p>${allowedDossier(h)?'<button class="btn btn-primary" id="unlockDossier">Visualizza il dossier completo · 49 €</button>':`<p class="small">Rispondi almeno a una domanda per personalizzare il dossier. Non serve completare tutte le verifiche: puoi proseguire anche con questioni aperte.</p><button class="btn btn-outline" data-jump="questions">Continua con le domande</button>`}</div>`}
function overviewTab(h){if(!h.analysis)return old_overviewTab(h);const q=questionCounts(h);return `<div class="overview-stack"><div class="overview-intro"><div><h2>La situazione della tua casa</h2><p>Cosa hai già chiarito, cosa manca e come puoi proseguire prima di fare un'offerta.</p></div><span class="subtle-pill">Aggiornato ${new Date(h.updatedAt).toLocaleDateString('it-IT')}</span></div>${journeyHeader(h)}${previewPanel(h)}<section class="surface-card"><div class="section-line"><div><h3>Le domande da chiarire</h3><p class="small muted">Rispondi ai temi segnalati e decidi quali considerare chiusi.</p></div><button class="btn btn-primary btn-small" data-jump="questions">${questionDone(h)?'Rivedi le risposte':'Rispondi alle domande'}</button></div>${currentBatch(h).slice(0,5).map(x=>`<div class="question-brief"><strong>${safe(x.title)}</strong><span class="status-tag ${x.state.closed?'status-documented':'status-missing'}">${x.state.closed?'Chiusa da te':x.state.answer?'Risposta inserita · aperta':'Da chiarire'}</span></div>`).join('')}${q.total>5?`<p class="tiny">Altre domande disponibili man mano che approfondisci</p>`:''}</section><div class="overview-two-col"><section class="surface-card"><h3>Verifiche e dossier</h3><p class="muted">Tutte le 9 aree di controllo, con approfondimenti relativi alla tua casa. Il dossier completo si può acquistare dopo aver iniziato a rispondere, anche con questioni aperte.</p>${dossierOffer(h)}</section><section class="surface-card"><h3>Vuoi approfondire un punto?</h3><p class="muted">Puoi caricare documenti, chiedere all'AI o scegliere un professionista per una specifica questione.</p><div class="flex wrap mt2"><button class="btn btn-outline btn-small" data-jump="documents">Aggiungi documento</button><button class="btn btn-outline btn-small" data-jump="chat">Chiedi all'AI</button><button class="btn btn-outline btn-small" data-jump="experts">Professionisti</button></div></section></div>${h.expertReports.length?`<section class="surface-card"><h3>Report ricevuti (simulazione)</h3>${h.expertReports.map(r=>`<p><b>${safe(r.expertName)}</b> — ${safe(r.categoryLabel)} · report esemplificativo incluso nel servizio</p>`).join('')}<button class="btn btn-outline" data-jump="experts">Apri i report</button></section>`:''}<section class="surface-card"><div class="section-line"><div><h3>La tua decisione</h3><p class="small muted">Puoi registrarla ora, modificarla o continuare a valutare altre case.</p></div><button class="btn btn-primary btn-small" data-jump="decision">Registra la decisione</button></div>${h.decisionReview?`<b>${safe(h.decisionReview.label)}</b>`:'Non hai ancora registrato una decisione su questa casa.'}</section><section class="surface-card"><h3>Ultimi aggiornamenti</h3>${activityHistory(h)}</section></div>`}
function questionsTab(h){ensureHomeFlow(h);if(!h.analysis)return `<section class="surface-card"><h2>Prima analizza l’immobile</h2><p>Inserisci la descrizione per generare domande specifiche.</p><button class="btn btn-primary" id="questionsAnalyze">Avvia analisi</button></section>`;
 h.questionsVisited=true;
 const shown=currentBatch(h),remaining=remainingQuestions(h),c=questionCounts(h),vis=h.visitStatus==='visited';
 const done=questionList(h).filter(x=>x.state.answer?.trim()).length;
 const future=questionList(h).filter(q=>q.phase==='after_visit'&&!vis&&!q.state.answer).length;
 return `<div class="overview-stack"><div class="overview-intro"><div><h2>Le domande sulla tua casa</h2><p>Partiamo da pochi aspetti importanti. MTG ti pone soltanto le domande più utili ora. Gli altri controlli sono conservati nel dossier.</p></div><span class="subtle-pill">${done} risposte · ${shown.length} domande proposte</span></div>
 <section class="surface-card"><h3>A che punto sei con questa casa?</h3><p class="muted small">Puoi iniziare dall'annuncio, anche se non hai visitato l'immobile.</p><div class="visit-options"><label><input type="radio" name="visitStatus" value="not_visited" ${!vis?'checked':''}> Non l'ho ancora visitata</label><label><input type="radio" name="visitStatus" value="visited" ${vis?'checked':''}> L'ho già visitata</label></div>${vis?`<div class="field mt2"><label class="label">Che cosa hai notato durante la visita? (facoltativo)</label><textarea id="visitNotes" rows="2" placeholder="Es. luminosità, rumori, umidità, spazi">${safe(h.visitNotes)}</textarea></div>`:''}<p class="tiny mt2">Documenti raccolti: ${h.docs.length}. La visita e i documenti sono indipendenti.</p><button class="btn btn-outline btn-small" data-jump="documents">Carica un nuovo documento</button></section>
 <section class="surface-card"><div class="section-line"><div><h3>Da dove iniziamo</h3><p class="small muted">Domande ordinate in base a conseguenze possibili, indizi dell'annuncio e tue priorità. Non sono tutte obbligatorie.</p></div><span class="state-pill">${shown.length} in evidenza</span></div><p class="tiny">${remaining.length} altre domande possibili${future?` · ${future} domande da affrontare dopo la visita`:''}. Puoi decidere quando approfondire.</p></section>
 ${shown.map((x,i)=>`<article class="surface-card question-item"><div class="section-line"><div><div class="eyebrow">${safe(CATEGORIES.find(z=>z[0]===x.category)?.[1]||'Verifica')} · ${i+1} di ${shown.length}</div><h3>${safe(x.title)}</h3></div>${badge(x.severity)}</div><p class="small muted">${safe(x.reason||'')}</p><label class="label" for="qa-${i}">La tua risposta</label><textarea id="qa-${i}" class="question-answer" data-q-answer="${safe(x.key)}" rows="2" placeholder="Rispondi con quello che sai. Puoi anche scrivere «Non lo so»." >${safe(x.state.answer)}</textarea><div class="flex wrap mt2"><button class="btn btn-outline btn-small" data-challenge="${safe(x.key)}">${x.state.challenge?'Aggiorna l’osservazione AI':'Analizza la mia risposta'}</button><button class="btn btn-ghost btn-small" data-unsure="${safe(x.key)}">Non lo so</button><button class="btn btn-outline btn-small" data-upload-for="${safe(x.key)}">Aggiungi documento</button><button class="btn btn-outline btn-small" data-expert-for="${safe(x.category)}">Chiedi a un professionista</button></div>${x.state.challenge?`<div class="notice mt2"><b>Osservazione MTG</b><p>${safe(x.state.challenge)}</p></div>`:''}<div class="question-status mt2"><label><input type="checkbox" data-close-question="${safe(x.key)}" ${x.state.closed?'checked':''}> Per me questa questione è chiusa</label><span class="tiny">${x.state.closed?'Chiusa da te · non necessariamente documentata':'Ancora aperta'}</span></div></article>`).join('')}
 ${questionList(h).filter(q=>q.state.answer?.trim()&&!shown.some(x=>x.key===q.key)).length?`<details class="surface-card"><summary><b>Le risposte già date</b> · ${questionList(h).filter(q=>q.state.answer?.trim()&&!shown.some(x=>x.key===q.key)).length} precedenti</summary>${questionList(h).filter(q=>q.state.answer?.trim()&&!shown.some(x=>x.key===q.key)).map(x=>`<div class="file-row"><b>${safe(x.title)}</b><p class="small">${safe(x.state.answer)}</p><span class="tiny">${x.state.closed?'Chiusa da te':'Ancora aperta'}</span></div>`).join('')}</details>`:''}
 <section class="surface-card"><h3>Decidi tu quando approfondire</h3><p class="muted">Puoi leggere le prossime domande, caricare altri documenti o passare alla prima valutazione senza aver risposto a tutte.</p><div class="flex wrap mt2">${remaining.length?`<button class="btn btn-outline" id="showMoreQuestions">Approfondisci con altre ${Math.min(NEXT_BATCH_SIZE,remaining.length)} domande</button>`:''}<button class="btn btn-primary" data-jump="overview">Vai alla prima valutazione</button></div>${!hasBuyerInput(h)?'<p class="tiny mt2">Per simulare l’acquisto del dossier, fornisci almeno una risposta; puoi anche indicare «Non lo so».</p>':''}</section></div>`;
}
function gapsTab(h){if(!h.analysis)return old_gapsTab(h);if(!h.unlocked){return `<div class="overview-stack"><div class="overview-intro"><div><h2>Verifiche e dossier</h2><p>Puoi consultare le aree principali. Il dettaglio delle verifiche è incluso nel dossier digitale.</p></div></div>${previewPanel(h)}<section class="surface-card"><h3>Le aree da controllare</h3><div class="check-mini-list">${CATEGORIES.map(([id,label])=>`<div class="check-mini-row"><span>${safe(label)}</span><span class="status-tag">${normalizedStatus(h.analysis.criteria?.[id]?.status).name}</span></div>`).join('')}</div></section><section class="surface-card"><h3>Il dossier completo</h3>${dossierOffer(h)}</section></div>`}return old_gapsTab(h)}
function decisionTab(h){return `<div class="overview-stack"><div class="overview-intro"><div><h2>Come vuoi procedere con questa casa?</h2><p>La decisione resta tua. Anche se scegli di fare un'offerta, controlla le questioni non documentate.</p></div></div>${previewPanel(h)}<section class="surface-card"><form id="decisionForm"><div class="field"><label class="label">La tua scelta</label><label class="choice-row"><input type="radio" name="choice" value="proceed" ${h.decisionReview?.choice==='proceed'?'checked':''}> Intendo presentare un'offerta</label><label class="choice-row"><input type="radio" name="choice" value="investigate" ${!h.decisionReview||h.decisionReview.choice==='investigate'?'checked':''}> Voglio ancora approfondire</label><label class="choice-row"><input type="radio" name="choice" value="stop" ${h.decisionReview?.choice==='stop'?'checked':''}> Non voglio procedere</label></div><div class="field"><label class="label">Se scegli di non procedere, qual è il motivo principale?</label><select id="decisionReason" class="input"><option value="">Seleziona il motivo</option>${[['cost','Prezzo o costi'],['fit','Non risponde alle mie esigenze'],['technical','Problemi tecnici o documentali'],['location','Zona o posizione'],['alternative','Ho trovato un’altra casa'],['other','Altro motivo']].map(([k,l])=>`<option value="${k}" ${h.decisionReason===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label class="label">Note facoltative</label><textarea id="decisionNote" rows="2" placeholder="Aggiungi un dettaglio, se vuoi">${safe(h.decisionNote||'')}</textarea></div><button class="btn btn-primary" type="submit">Salva la mia decisione</button></form></section><section class="surface-card"><h3>Vuoi vedere un'altra casa?</h3><p>Il tuo profilo resta salvato. Puoi valutare una nuova casa e confrontarla con questa.</p><button class="btn btn-outline" id="decisionAddHome">+ Aggiungi un’altra casa</button></section></div>`}
function expertsTab(h){const q=questionList(h).filter(x=>!x.state.closed),freq={};q.forEach(x=>freq[x.category]=(freq[x.category]||0)+1);const preferred=Object.entries(freq).sort((a,b)=>b[1]-a[1])[0]?.[0]||'all';const experts=[...EXPERTS].map(e=>({...e,match:q.filter(x=>e.specialties.includes(x.category)).length})).sort((a,b)=>b.match-a.match||b.rating-a.rating);return `<div class="overview-stack"><div class="overview-intro"><div><h2>Trova il professionista adatto</h2><p>Prima i professionisti che possono occuparsi delle questioni ancora aperte sulla tua casa.</p></div><span class="subtle-pill">${q.length} questioni aperte</span></div><div class="notice">Profili, fotografie e recensioni sono simulati per il test MVP. Non sono prenotazioni reali.</div><section class="surface-card"><h3>Le questioni ancora aperte</h3><div class="flex wrap mt2">${q.length?q.map(x=>`<span class="chip">${safe(x.title)}</span>`).join(''):'<span class="muted">Nessuna questione aperta nel percorso. Puoi richiedere aiuto su altri temi.</span>'}</div></section><div class="grid grid-3" id="expertGrid">${experts.map(e=>`<div class="card expert-card"><div class="expert-head"><img class="pro-image" src="${e.photo}" alt="Foto illustrativa"><div><b>${safe(e.name)}</b><p class="small muted">${safe(e.job)}</p><div class="stars">★ ${String(e.rating).replace('.',',')} · ${e.reviews} recensioni simulate</div></div></div><p class="small muted">${safe(e.description)}</p><p class="small"><b>${e.match?e.match+' questioni pertinenti':'Altre competenze'}</b></p><button class="btn btn-primary btn-full" data-book="${e.id}" data-cat="${preferred}">Vedi servizi e prezzi</button><p class="tiny">Profilo e recensioni simulati</p></div>`).join('')}</div><section class="surface-card"><h3>Hai bisogno di aiuto su un altro argomento?</h3><p class="muted">Descrivi ciò che vuoi verificare. MTG individua la specializzazione più pertinente tra quelle disponibili.</p><textarea id="expertOther" rows="2" maxlength="300" placeholder="Es. Vorrei capire se posso abbattere una parete">${safe(h.specialRequest)}</textarea><button class="btn btn-outline mt2" id="findOtherExpert">Cerca altri professionisti</button><div id="otherExpertResult" class="mt2"></div></section><section class="surface-card"><h3>I tuoi report professionali</h3><p class="small muted">Il report è incluso nel servizio richiesto. Le simulazioni non costituiscono perizie.</p>${h.expertReports.map(r=>`<div class="file-row"><b>${safe(r.expertName)}</b> · ${safe(r.categoryLabel)}<p class="small muted">${safe(r.summary)}</p><span class="chip">Report dimostrativo</span></div>`).join('')||'<p class="muted">Non ci sono ancora report di esempio.</p>'}</section></div>`}
function comparePage(){const html=old_comparePage();return html.replace('Una decisione, più alternative','Le tue case, a confronto').replace('Fit, Readiness, gap aperti e costi non vengono fusi in un voto unico.','Preferenze condivise, informazioni disponibili e questioni aperte per ogni immobile.').replace('Completezza del dossier','Informazioni documentate').replace('Rispondenza alle esigenze','Quanto fa per te').replace('Gap prioritari','Questioni da chiarire')+`<div class="container"><section class="surface-card"><h3>Confronto dettagliato</h3><p>Il confronto di base è gratuito. Le spiegazioni delle verifiche e le fonti sono consultabili soltanto per gli immobili con dossier sbloccato.</p><div class="grid grid-3">${S.homes.filter(h=>compareSelection.includes(h.id)).map(h=>`<div><b>${safe(h.name)}</b><p class="small">${h.unlocked?'Dossier completo disponibile':'Valutazione gratuita'}</p>${h.unlocked?`<p class="tiny">${gapList(h).length} verifiche con dettaglio consultabile</p>`:`<button class="btn btn-outline btn-small" data-buy-compare="${h.id}">Completa dossier · 49 €</button>`}</div>`).join('')}</div></section></div>`}
function reviewPanel(h){return old_reviewPanel(h).replace('La tua valutazione attuale','La tua decisione').replace('Non fa per me','Non voglio procedere')}
function intentDossier(h){if(!allowedDossier(h)){tab='questions';render();toast('Rispondi ad almeno una domanda sulla casa, anche con «Non lo so».');return}old_intentDossier(h)}
function expertModal(id,cat){const e=EXPERTS.find(x=>x.id===id),h=H();if(!e||!h)return;const open=questionList(h).filter(x=>!x.state.closed&&e.specialties.includes(x.category));const match=open.length?open:questionList(h).filter(x=>e.specialties.includes(x.category));const initial=match.slice(0,2).map(x=>x.key);track('expert_profile_view',{expertId:id,propertyId:h.id,matched:match.length});openModal(`<div class="flex between"><h2>${safe(e.name)} · ${safe(e.job)}</h2><button class="btn btn-outline btn-small" data-close>Chiudi</button></div><p class="muted">Scegli gli aspetti da includere nell'incarico. Il report sui temi selezionati è compreso nel servizio.</p><div class="notice">Profilo e recensioni simulati. Nessun appuntamento né pagamento reale.</div><div class="mt2"><b>Questioni da affidare al professionista</b>${match.map((x,i)=>`<label class="scope-row"><input type="checkbox" data-scope="${safe(x.key)}" ${initial.includes(x.key)?'checked':''}> ${safe(x.title)}</label>`).join('')||'<p class="small muted">Nessuna questione pertinente ancora aperta. Puoi descrivere un’altra richiesta.</p>'}<div class="field"><label class="label">Un altro aspetto da valutare (facoltativo)</label><textarea rows="2" id="scopeOther" placeholder="Descrivi l’approfondimento richiesto..."></textarea></div></div><div class="grid mt2">${SERVICE.filter(s=>s.id==='video'||s.id==='visit'||s.id==='message').map(s=>`<div class="file-row flex between wrap"><div><b>${safe(s.name)}</b><p class="tiny">${safe(s.desc)}</p></div><div><strong>${money(s.price)}</strong> <button class="btn btn-primary btn-small" data-expert-svc="${s.id}">Scegli</button></div></div>`).join('')}</div><p class="tiny">Il prezzo base è un'ipotesi di test. Perimetri aggiuntivi possono richiedere un preventivo supplementare, non ancora definito.</p>`);$$('[data-expert-svc]').forEach(b=>b.onclick=()=>{const keys=$$('[data-scope]:checked').map(x=>x.dataset.scope),other=$('#scopeOther').value.trim();if(!keys.length&&!other)return toast('Seleziona almeno una questione o descrivi la tua richiesta.');intentExpert(e,cat,b.dataset.expertSvc,keys,other)})}
function intentExpert(e,cat,serviceId,keys=[],other=''){const s=SERVICE.find(x=>x.id===serviceId),h=H();if(!s||!h)return;const names=questionList(h).filter(x=>keys.includes(x.key)).map(x=>x.title);const count=names.length;const extra=count>2||!!other;const scope=[...names,...(other?[other]:[])];const detail=`Comprende il report sulle questioni indicate: ${scope.join('; ')}. ${extra?'Il prezzo di eventuali verifiche aggiuntive sarà da concordare e non è simulato in questo test.':''} Non sarà erogata una prestazione reale.`;track('expert_offer_view',{expertId:e.id,propertyId:h.id,service:serviceId,scopeCount:scope.length,basePrice:s.price,extraPricingPending:extra});confirmIntent(`${s.name} · ${e.name}`,s.price,detail,()=>{S.intents.push({id:uid(),time:now(),type:'expert',propertyId:h.id,expertId:e.id,service:serviceId,category:cat,scope,basePrice:s.price,extraPricingPending:extra});track('payment_intent',{product:'expert_'+serviceId,propertyId:h.id,basePrice:s.price,scopeCount:scope.length,extraPricingPending:extra,realPayment:false});persist();setTimeout(()=>demoExpertReportOffer(e,cat,serviceId,scope),150)})}
function demoExpertReportOffer(e,cat,serviceId,scope=[]){const h=H();openModal(`<h2>Richiesta registrata</h2><div class="notice">Acquisto simulato. Nessun pagamento o incarico reale.</div><p>Il report sulle questioni selezionate è <b>incluso nel prezzo della prestazione</b>. Puoi visualizzare un report esemplificativo e poi continuare la valutazione della casa.</p><button class="btn btn-primary btn-full mt2" id="integrateExpert">Visualizza e aggiungi report di esempio</button><button class="btn btn-outline btn-full mt2" data-close>Non adesso</button>`);$('#integrateExpert').onclick=async()=>{const report={id:uid(),expertId:e.id,expertName:e.name,category:cat,categoryLabel:CATEGORIES.find(x=>x[0]===cat)?.[1]||cat,service:serviceId,scope,date:now(),simulation:true,summary:`Report dimostrativo relativo a: ${scope.join('; ')||'approfondimento richiesto'}. Le evidenze effettive restano da acquisire; nessuna conformità è attestata.`,findings:scope.map(item=>({item,status:'Da approfondire',source:'Esempio simulato',action:'Richiedere riscontro professionale reale'}))};h.expertReports.push(report);h.reportScenario=true;persist();track('expert_report_demo_integrated',{propertyId:h.id,scopeCount:scope.length});closeModal();await analyze(h);tab='overview';render();toast('Report di esempio integrato. Puoi continuare con le domande e la tua decisione.')}}
function exportDossier(h){if(!h.unlocked)return toast('Dossier non ancora sbloccato');const t=[`MTG — DOSSIER DIMOSTRATIVO`,h.name,`Quanto fa per te: ${fit(h)??'n/d'}`,`Informazioni documentate: ${readiness(h)??'n/d'}%`,'',...questionList(h).flatMap(x=>[`VERIFICA: ${x.title}`,`Risposta: ${x.state.answer||'Non disponibile'}`,`Stato dichiarato buyer: ${x.state.closed?'Chiusa da te':'Aperta'}`,`Osservazione AI: ${x.state.challenge||'Non esaminata'}`,`Evidenza: ${x.reason||''}`,'']),...h.expertReports.map(r=>`REPORT SIMULATO: ${r.summary}`),'Nessuna verifica tecnica reale è stata effettuata.'].join('\n');const u=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='MTG_dossier_'+h.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);track('dossier_export',{propertyId:h.id})}
function bindProperty(){old_bindProperty();const h=H();if(!h)return;$('#addAnotherHome')?.addEventListener('click',()=>{track('additional_property_started',{fromProperty:h.id});go('home')});if(tab==='questions'){$$('[name="visitStatus"]').forEach(el=>el.onchange=()=>{const old=h.visitStatus;h.visitStatus=el.value;h.phaseHistory.push({date:now(),from:old,to:el.value});persist();track('property_visit_status',{propertyId:h.id,status:el.value});render()});$('#visitNotes')?.addEventListener('change',el=>{h.visitNotes=el.target.value.trim();persist()});$('#questionsAnalyze')?.addEventListener('click',()=>analyze(h));$('#showMoreQuestions')?.addEventListener('click',()=>expandBatch(h));$$('[data-q-answer]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.qAnswer;h.questionStates[k]||={};h.questionStates[k].answer=el.value.trim();h.updatedAt=now();persist();track('buyer_question_answered',{propertyId:h.id,questionKey:k,unknown:/^non lo so$/i.test(el.value.trim())});render()}));$$('[data-unsure]').forEach(b=>b.onclick=()=>{const k=b.dataset.unsure;h.questionStates[k]||={};h.questionStates[k].answer='Non lo so';persist();render()});$$('[data-close-question]').forEach(b=>b.onchange=()=>{const k=b.dataset.closeQuestion;h.questionStates[k]||={};h.questionStates[k].closed=b.checked;persist();track('buyer_question_status',{propertyId:h.id,closed:b.checked});render()});$$('[data-challenge]').forEach(b=>b.onclick=()=>challengeBuyer(h,b.dataset.challenge));$$('[data-upload-for]').forEach(b=>b.onclick=()=>{tab='documents';render()});$$('[data-expert-for]').forEach(b=>b.onclick=()=>{tab='experts';render()})}if(tab==='decision'){$('#decisionForm')?.addEventListener('submit',e=>{e.preventDefault();const choice=$('input[name="choice"]:checked')?.value||'investigate',reason=$('#decisionReason').value;if(choice==='stop'&&!reason){toast('Indica perché hai deciso di non procedere.');return}const labels={proceed:'Intendo fare un’offerta',investigate:'Voglio ancora approfondire',stop:'Non voglio procedere'};h.decisionReview={choice,label:labels[choice],date:now(),fit:fit(h),readiness:readiness(h)};h.decisionReason=choice==='stop'?reason:'';h.decisionNote=$('#decisionNote').value.trim();persist();track('decision_review',{propertyId:h.id,choice,reason:h.decisionReason});render();toast('Decisione salvata')});$('#decisionAddHome')?.addEventListener('click',()=>go('home'))}if(tab==='experts'){bindExpertCards();$('#findOtherExpert')?.addEventListener('click',()=>findOtherExperts(h))}if(tab==='gaps'){$$('[data-experts-gap]').forEach(b=>b.onclick=()=>{tab='experts';render()})}if(tab==='gaps'){const buy=$('#unlockDossier');if(buy)buy.onclick=()=>intentDossier(h)} }
async function challengeBuyer(h,k){
 const item=questionList(h).find(x=>x.key===k);if(!item)return;
 const state=h.questionStates[k]||={};const answer=state.answer?.trim();
 if(!answer){toast('Scrivi prima la tua risposta oppure «Non lo so».');return}
 let challenge='[ESEMPIO] Informazione ancora da confermare. Puoi chiedere il documento pertinente o lasciare aperta la questione.';
 let followUps=[];
 try{
  if(aiReady()&&authenticated()){
   const result=await useAI('review_answer',{question:{check_id:item.check_id,category:item.category,phase:item.phase,title:item.title,reason:item.reason},answer,visitStatus:h.visitStatus,property:{description:h.listingText,area:h.area,price:h.price,sqm:h.sqm},buyerProfile:S.buyerProfile,previousQuestions:questionList(h).map(x=>({check_id:x.check_id,title:x.title})).slice(0,32)});
   challenge=result.assessment||challenge;followUps=result.follow_ups||[];
  }
 }catch(e){toast('Analisi AI non disponibile: '+e.message);return}
 state.challenge=challenge;state.challengedAt=now();const added=markFollowUps(h,k,followUps);
 persist();track('buyer_answer_challenged',{propertyId:h.id,questionKey:k,followups:added,mode:aiReady()&&authenticated()?'ai':'demo'});render();
 if(added)toast(`Aggiunt${added===1?'a':'e'} ${added} domand${added===1?'a':'e'} di approfondimento`);
}
async function findOtherExperts(h){const q=$('#expertOther')?.value.trim();if(!q)return toast('Descrivi l’argomento da approfondire');h.specialRequest=q;persist();const lower=q.toLowerCase();const tags={urban:/paret|muro|ediliz|catast|planimetr|ristruttur/,risk:/amiant|frana|alluvion|struttur|crep/,condition:/umid|infiltr|impiant|caldai|lavor/,energy:/energet|ape|isolament/,price:/prezz|mutuo|costi/,condo:/condomin|assemblea|spese/,location:/zona|quartier|trasport/,legal:/rogito|vincol|contratt|ipotec/};let categories=Object.entries(tags).filter(([c,re])=>re.test(lower)).map(([c])=>c);if(!categories.length&&aiReady()&&authenticated()){try{const data=await useAI('match_expert',{question:q});categories=Array.isArray(data.categories)?data.categories:[]}catch{}}const ranked=[...EXPERTS].map(e=>({...e,matches:e.specialties.filter(c=>categories.includes(c)).length})).sort((a,b)=>b.matches-a.matches||b.rating-a.rating);const matches=ranked.filter(e=>e.matches>0);const target=$('#otherExpertResult');target.innerHTML=`<p class="small">${matches.length?'Professionisti con specializzazione pertinente:':'Non è stata trovata una corrispondenza certa nel catalogo dimostrativo.'}</p>${(matches.length?matches:ranked.slice(0,3)).slice(0,3).map(e=>`<div class="file-row flex between wrap"><div><b>${safe(e.name)}</b><p class="tiny">${safe(e.job)} · profilo simulato</p></div><button class="btn btn-outline btn-small" data-custom-book="${e.id}">Vedi servizi</button></div>`).join('')}`;$$('[data-custom-book]').forEach(b=>b.onclick=()=>expertModal(b.dataset.customBook,categories[0]||'other'));track('expert_custom_search',{propertyId:h.id,matched:matches.length})}

$('#brand').onclick=e=>{e.preventDefault();go('home')};$('#navHomes').onclick=()=>go('list');$('#navCompare').onclick=()=>go('compare');$('#navMethod').onclick=()=>go('method');$('#navAccount').onclick=()=>{if(!authenticated())return startAuth();openModal(`<h2>Account MTG</h2><p>${safe(session.user.email)}</p><p class="muted">Analisi AI disponibile con la tua connessione Supabase.</p><button class="btn btn-outline" id="logOut">Esci</button>`);$('#logOut').onclick=async()=>{await supabase.auth.signOut();closeModal();render()}};$('#privacyBtn').onclick=()=>openModal(`<h2>Informazioni sul prototipo</h2><p>Mind The Gap è un prototipo di test. Nomi, ritratti, recensioni, prezzi dei servizi e report degli esperti sono simulati. I click di acquisto non comportano addebiti.</p><p>Le proprietà e i metadati restano salvati nel browser; i testi dei documenti vengono salvati in IndexedDB sul dispositivo. Quando richiedi un'analisi reale, i testi forniti sono trasmessi alla tua Edge Function Supabase e quindi a OpenAI.</p><p>Nessuna risposta sostituisce una verifica di regolarità urbanistica, catastale, giuridica o tecnica.</p><button class="btn btn-outline" data-close>Chiudi</button>`);$('#modal').onclick=e=>{if(e.target.matches('.modal-backdrop'))closeModal()};
render();initSupabase();
